// Original game-owned care/restaurant art and readable task metadata; no remote assets.
export const DENTAL_TASKS={dirt:{name:'Dirty patches',tool:'brush'},plaque:{name:'Plaque',tool:'water'},food:{name:'Trapped food',tool:'pick'},candy:{name:'Sticky candy',tool:'pick'},cavity:{name:'Cavities',tool:'fill'},loose:{name:'Loose teeth',tool:'pull'},polish:{name:'Dull enamel',tool:'polish'},missing:{name:'Missing teeth',tool:'replace'},crooked:{name:'Crooked teeth',tool:'align'}};
export function cafeGuest(order){return ['Fern','Pip','Nova','Moss'][order.id%4];}
export function cafePlateStatus(m){const o=m.orders[m.orderIndex||0];if(!o)return 'Choose a guest.';const want=o.recipe.items,plate=m.plate,counts=items=>items.reduce((all,id)=>(all[id]=(all[id]||0)+1,all),{}),need=counts(want),have=counts(plate),extra=Object.keys(have).some(id=>have[id]>(need[id]||0)),missing=Object.keys(need).reduce((n,id)=>n+Math.max(0,need[id]-(have[id]||0)),0);if(!plate.length)return 'Start with the recipe above.';if(extra)return 'Extra ingredient: tap it on the plate to remove it.';if(missing)return missing+' more ingredient'+(missing===1?'':'s')+' needed.';if(o.sequence&&want.join('|')!==plate.join('|'))return 'Ingredients match. Rebuild in the numbered order.';return 'Recipe matched. Ready to serve!';}
export function drawCareBackdrop(c,kind){const g=c.createLinearGradient(0,0,0,640);g.addColorStop(0,kind==='cafe'?'#203c40':'#29374c');g.addColorStop(1,kind==='cafe'?'#345050':'#354857');c.fillStyle=g;c.fillRect(0,0,1000,640);c.strokeStyle='#a4b9b518';c.lineWidth=1;for(let x=0;x<1000;x+=65)for(let y=90;y<560;y+=65)c.strokeRect(x,y,65,65);
 for(const side of [0,1]){const x=side?820:35;c.fillStyle='#637d792e';c.fillRect(x,150,145,9);c.fillRect(x,340,145,9);for(let i=0;i<3;i++){c.fillStyle=['#aaa4be','#a0bca8','#d1bb90'][i]+'88';c.beginPath();c.roundRect(x+15+i*40,110,24,40,5);c.fill();c.fillStyle='#d4c9b3';c.fillRect(x+18+i*40,107,18,5);}}
 if(kind==='cafe'){for(const x of [220,780]){c.strokeStyle='#b6a789';c.lineWidth=3;c.beginPath();c.moveTo(x,0);c.lineTo(x,95);c.stroke();c.fillStyle='#cfb38b';c.beginPath();c.ellipse(x,100,38,12,0,0,Math.PI*2);c.fill();c.fillStyle='#edd29c25';c.beginPath();c.moveTo(x-28,105);c.lineTo(x-90,290);c.lineTo(x+90,290);c.lineTo(x+28,105);c.closePath();c.fill();}}
}
export function drawEnamel(c,w,h){const g=c.createLinearGradient(-w/2,-h/2,w/2,h/2);g.addColorStop(0,'#fffdf1');g.addColorStop(.55,'#e6eadc');g.addColorStop(1,'#aebfc1');c.beginPath();c.moveTo(-w*.45,-h*.18);c.bezierCurveTo(-w*.62,-h*.66,-w*.18,-h*.58,0,-h*.44);c.bezierCurveTo(w*.3,-h*.61,w*.6,-h*.5,w*.46,-h*.12);c.lineTo(w*.27,h*.47);c.quadraticCurveTo(w*.13,h*.6,0,h*.28);c.quadraticCurveTo(-w*.16,h*.59,-w*.28,h*.45);c.closePath();c.fillStyle=g;c.fill();c.strokeStyle='#aab4bb';c.lineWidth=1.6;c.stroke();c.beginPath();c.moveTo(-w*.27,-h*.28);c.quadraticCurveTo(-w*.34,-h*.02,-w*.22,h*.14);c.strokeStyle='#ffffffa0';c.lineWidth=3;c.stroke();}
